18	namespace NzbDrone.Core.Download
19	{
20	    public interface ICompletedDownloadService
21	    {
22	        void Check(TrackedDownload trackedDownload);
23	        void Import(TrackedDownload trackedDownload);
24	        bool VerifyImport(TrackedDownload trackedDownload, List<ImportResult> importResults);
25	    }
