27	    public class CompletedDownloadService : ICompletedDownloadService
28	    {
29	        private readonly IEventAggregator _eventAggregator;
30	        private readonly IHistoryService _historyService;
31	        private readonly IProvideImportItemService _provideImportItemService;
32	        private readonly IDownloadedEpisodesImportService _downloadedEpisodesImportService;
33	        private readonly IParsingService _parsingService;
34	        private readonly ISeriesService _seriesService;
35	        private readonly ITrackedDownloadAlreadyImported _trackedDownloadAlreadyImported;
36	        private readonly IEpisodeService _episodeService;
37	        private readonly IMediaFileService _mediaFileService;
38	        private readonly IRejectedImportService _rejectedImportService;
39	        private readonly IRejectedFileExtensionService _rejectedFileExtensionService;
40	        private readonly IProvideDownloadClient _downloadClientProvider;
41	        private readonly Logger _logger;
42	
43	        public CompletedDownloadService(IEventAggregator eventAggregator,
44	                                        IHistoryService historyService,
45	                                        IProvideImportItemService provideImportItemService,
46	                                        IDownloadedEpisodesImportService downloadedEpisodesImportService,
47	                                        IParsingService parsingService,
48	                                        ISeriesService seriesService,
49	                                        ITrackedDownloadAlreadyImported trackedDownloadAlreadyImported,
50	                                        IEpisodeService episodeService,
51	                                        IMediaFileService mediaFileService,
52	                                        IRejectedImportService rejectedImportService,
53	                                        IRejectedFileExtensionService rejectedFileExtensionService,
54	                                        IProvideDownloadClient downloadClientProvider,
55	                                        Logger logger)
56	        {
57	            _eventAggregator = eventAggregator;
58	            _historyService = historyService;
59	            _provideImportItemService = provideImportItemService;
60	            _downloadedEpisodesImportService = downloadedEpisodesImportService;
61	            _parsingService = parsingService;
62	            _seriesService = seriesService;
63	            _trackedDownloadAlreadyImported = trackedDownloadAlreadyImported;
64	            _episodeService = episodeService;
65	            _mediaFileService = mediaFileService;
66	            _rejectedImportService = rejectedImportService;
67	            _rejectedFileExtensionService = rejectedFileExtensionService;
68	            _downloadClientProvider = downloadClientProvider;
69	            _logger = logger;
70	        }
71	
72	        public void Check(TrackedDownload trackedDownload)
73	        {
74	            if (trackedDownload.DownloadItem.Status != DownloadItemStatus.Completed)
75	            {
76	                return;
77	            }
78	
79	            SetImportItem(trackedDownload);
80	
81	            // Only process tracked downloads that are still downloading or have been blocked for importing due to an issue with matching
82	            if (trackedDownload.State != TrackedDownloadState.Downloading && trackedDownload.State != TrackedDownloadState.ImportBlocked)
83	            {
84	                return;
85	            }
86	
87	            var grabbedHistories = _historyService.FindByDownloadId(trackedDownload.DownloadItem.DownloadId).Where(h => h.EventType == EpisodeHistoryEventType.Grabbed).ToList();
88	            var historyItem = grabbedHistories.MaxBy(h => h.Date);
89	
90	            if (historyItem == null && trackedDownload.DownloadItem.Category.IsNullOrWhiteSpace())
91	            {
92	                trackedDownload.Warn("Download wasn't grabbed by Sonarr and not in a category, Skipping.");
93	                return;
94	            }
95	
96	            if (!ValidatePath(trackedDownload))
97	            {
98	                return;
99	            }
100	
101	            var series = _parsingService.GetSeries(trackedDownload.DownloadItem.Title);
102	
103	            if (series == null)
104	            {
105	                if (historyItem != null)
106	                {
107	                    series = _seriesService.GetSeries(historyItem.SeriesId);
108	                }
109	
110	                if (series == null)
111	                {
112	                    trackedDownload.Warn("Series title mismatch; automatic import is not possible. Check the download troubleshooting entry on the wiki for common causes.");
113	                    SetStateToImportBlocked(trackedDownload);
114	
115	                    return;
116	                }
117	
118	                Enum.TryParse(historyItem.Data.GetValueOrDefault(EpisodeHistory.SERIES_MATCH_TYPE, SeriesMatchType.Unknown.ToString()), out SeriesMatchType seriesMatchType);
119	                Enum.TryParse(historyItem.Data.GetValueOrDefault(EpisodeHistory.RELEASE_SOURCE, ReleaseSourceType.Unknown.ToString()), out ReleaseSourceType releaseSource);
120	
121	                // Show a warning if the release was matched by ID and the source is not interactive search
122	                if (seriesMatchType == SeriesMatchType.Id && releaseSource != ReleaseSourceType.InteractiveSearch)
123	                {
124	                    trackedDownload.Warn("Found matching series via grab history, but release was matched to series by ID. Automatic import is not possible. See the FAQ for details.");
125	                    SetStateToImportBlocked(trackedDownload);
126	
127	                    return;
128	                }
129	            }
130	
131	            trackedDownload.State = TrackedDownloadState.ImportPending;
132	        }
133	
134	        public void Import(TrackedDownload trackedDownload)
135	        {
136	            SetImportItem(trackedDownload);
137	
138	            if (!ValidatePath(trackedDownload))
139	            {
140	                return;
141	            }
142	
143	            if (trackedDownload.RemoteEpisode == null)
144	            {
145	                trackedDownload.Warn("Unable to parse download, automatic import is not possible.");
146	                SetStateToImportBlocked(trackedDownload);
147	
148	                return;
149	            }
150	
151	            trackedDownload.State = TrackedDownloadState.Importing;
152	
153	            var outputPath = trackedDownload.ImportItem.OutputPath.FullPath;
154	            var importResults = _downloadedEpisodesImportService.ProcessPath(outputPath,
155	                ImportMode.Auto,
156	                trackedDownload.RemoteEpisode.Series,
157	                trackedDownload.ImportItem);
158	
159	            if (VerifyImport(trackedDownload, importResults))
160	            {
161	                return;
162	            }
163	
164	            trackedDownload.State = TrackedDownloadState.ImportPending;
165	
166	            if (importResults.Empty())
167	            {
168	                if (ProcessRejectedDownloadClientFiles(trackedDownload))
169	                {
170	                    return;
171	                }
172	
173	                trackedDownload.Warn("No files found are eligible for import in {0}", outputPath);
174	
175	                return;
176	            }
177	
178	            if (importResults.Count == 1)
179	            {
180	                var firstResult = importResults.First();
181	
182	                if (_rejectedImportService.Process(trackedDownload, firstResult))
183	                {
184	                    if (trackedDownload.State != TrackedDownloadState.FailedPending)
185	                    {
186	                        SetStateToImportBlocked(trackedDownload);
187	                    }
188	
189	                    return;
190	                }
191	
192	                if (firstResult.ImportDecision.Rejections.FirstOrDefault()?.Reason == ImportRejectionReason.MultiSeason)
193	                {
194	                    trackedDownload.Warn(new TrackedDownloadStatusMessage(trackedDownload.DownloadItem.Title, firstResult.Errors));
195	                    SetStateToImportBlocked(trackedDownload);
196	                    return;
197	                }
198	            }
199	
200	            var statusMessages = new List<TrackedDownloadStatusMessage>
201	                                 {
202	                                    new TrackedDownloadStatusMessage("One or more episodes expected in this release were not imported or missing from the release", new List<string>())
203	                                 };
204	
205	            if (importResults.Any(c => c.Result != ImportResultType.Imported))
206	            {
207	                statusMessages.AddRange(
208	                    importResults
209	                        .Where(v => v.Result != ImportResultType.Imported && v.ImportDecision.LocalEpisode != null)
210	                        .OrderBy(v => v.ImportDecision.LocalEpisode.Path)
211	                        .Select(v =>
212	                            new TrackedDownloadStatusMessage(Path.GetFileName(v.ImportDecision.LocalEpisode.Path),
213	                                v.Errors)));
214	            }
215	
216	            if (statusMessages.Any())
217	            {
218	                trackedDownload.Warn(statusMessages.ToArray());
219	                SetStateToImportBlocked(trackedDownload);
220	            }
221	        }
222	
223	        public bool VerifyImport(TrackedDownload trackedDownload, List<ImportResult> importResults)
224	        {
225	            var allEpisodesImported = importResults.Where(c => c.Result == ImportResultType.Imported)
226	                                                   .SelectMany(c => c.ImportDecision.LocalEpisode.Episodes)
227	                                                   .Count() >= Math.Max(1,
228	                                          trackedDownload.RemoteEpisode.Episodes.Count);
229	
230	            var historyItems = _historyService.FindByDownloadId(trackedDownload.DownloadItem.DownloadId)
231	                .OrderByDescending(h => h.Date)
232	                .ToList();
233	
234	            var grabbedHistory = historyItems.Where(h => h.EventType == EpisodeHistoryEventType.Grabbed).ToList();
235	            var releaseInfo = grabbedHistory.Count > 0 ? new GrabbedReleaseInfo(grabbedHistory) : null;
236	
237	            if (allEpisodesImported)
238	            {
239	                _logger.Debug("All episodes were imported for {0}", trackedDownload.DownloadItem.Title);
240	                trackedDownload.State = TrackedDownloadState.Imported;
241	
242	                _eventAggregator.PublishEvent(new DownloadCompletedEvent(trackedDownload,
243	                    trackedDownload.RemoteEpisode.Series.Id,
244	                    importResults.Where(c => c.Result == ImportResultType.Imported).Select(c => c.EpisodeFile).ToList(),
245	                    releaseInfo));
246	
247	                return true;
248	            }
249	
250	            // Double check if all episodes were imported by checking the history if at least one
251	            // file was imported. This will allow the decision engine to reject already imported
252	            // episode files and still mark the download complete when all files are imported.
253	
254	            // EDGE CASE: This process relies on EpisodeIds being consistent between executions, if a series is updated
255	            // and an episode is removed, but later comes back with a different ID then Sonarr will treat it as incomplete.
256	            // Since imports should be relatively fast and these types of data changes are infrequent this should be quite
257	            // safe, but commenting for future benefit.
258	
259	            var atLeastOneEpisodeImported = importResults.Any(c => c.Result == ImportResultType.Imported);
260	            var allEpisodesImportedInHistory = _trackedDownloadAlreadyImported.IsImported(trackedDownload, historyItems);
261	
262	            if (allEpisodesImportedInHistory)
263	            {
264	                // Log different error messages depending on the circumstances, but treat both as fully imported, because that's the reality.
265	                // The second message shouldn't be logged in most cases, but continued reporting would indicate an ongoing issue.
266	
267	                if (atLeastOneEpisodeImported)
268	                {
269	                    _logger.Debug("All episodes were imported in history for {0}", trackedDownload.DownloadItem.Title);
270	                }
271	                else
272	                {
273	                    _logger.ForDebugEvent()
274	                           .Message("No Episodes were just imported, but all episodes were previously imported, possible issue with download history.")
275	                           .Property("SeriesId", trackedDownload.RemoteEpisode.Series.Id)
276	                           .Property("DownloadId", trackedDownload.DownloadItem.DownloadId)
277	                           .Property("Title", trackedDownload.DownloadItem.Title)
278	                           .Property("Path", trackedDownload.ImportItem.OutputPath.ToString())
279	                           .WriteSentryWarn("DownloadHistoryIncomplete")
280	                           .Log();
281	                }
282	
283	                var episodes = _episodeService.GetEpisodes(trackedDownload.RemoteEpisode.Episodes.Select(e => e.Id));
284	                var files = _mediaFileService.GetFiles(episodes.Select(e => e.EpisodeFileId).Where(i => i > 0).Distinct());
285	
286	                trackedDownload.State = TrackedDownloadState.Imported;
287	                _eventAggregator.PublishEvent(new DownloadCompletedEvent(trackedDownload, trackedDownload.RemoteEpisode.Series.Id, files, releaseInfo));
288	
289	                return true;
290	            }
291	
292	            _logger.Debug("Not all episodes have been imported for the release '{0}'", trackedDownload.DownloadItem.Title);
293	            return false;
294	        }
295	
296	        private bool ProcessRejectedDownloadClientFiles(TrackedDownload trackedDownload)
297	        {
298	            var files = GetDownloadClientFiles(trackedDownload);
299	
300	            if (files.Empty())
301	            {
302	                return false;
303	            }
304	
305	            var rejection = _rejectedFileExtensionService.GetRejection(files.Select(f => f.RelativePath));
306	
307	            if (rejection == null)
308	            {
309	                return false;
310	            }
311	
312	            _logger.Debug("Download '{0}' has no files to import, but the download client reports a rejected file: {1}", trackedDownload.DownloadItem.Title, rejection.Message);
313	
314	            var importResult = new ImportResult(new ImportDecision(null, rejection), rejection.Message);
315	
316	            if (!_rejectedImportService.Process(trackedDownload, importResult))
317	            {
318	                return false;
319	            }
320	
321	            if (trackedDownload.State != TrackedDownloadState.FailedPending)
322	            {
323	                SetStateToImportBlocked(trackedDownload);
324	            }
325	
326	            return true;
327	        }
328	
329	        private List<DownloadClientFile> GetDownloadClientFiles(TrackedDownload trackedDownload)
330	        {
331	            try
332	            {
333	                var downloadClient = _downloadClientProvider.Get(trackedDownload.DownloadClient);
334	
335	                return downloadClient.GetFiles(trackedDownload.DownloadItem).ToList();
336	            }
337	            catch (Exception ex)
338	            {
339	                _logger.Debug(ex, "Unable to get files for download '{0}' from download client", trackedDownload.DownloadItem.Title);
340	
341	                return new List<DownloadClientFile>();
342	            }
343	        }
344	
345	        private void SetStateToImportBlocked(TrackedDownload trackedDownload)
346	        {
347	            trackedDownload.State = TrackedDownloadState.ImportBlocked;
348	
349	            if (!trackedDownload.HasNotifiedManualInteractionRequired)
350	            {
351	                _logger.Warn("Import blocked for '{0}': {1}", trackedDownload.DownloadItem.Title, trackedDownload.StatusMessages.SelectMany(m => m.Messages).ConcatToString("; "));
352	
353	                var grabbedHistories = _historyService.FindByDownloadId(trackedDownload.DownloadItem.DownloadId).Where(h => h.EventType == EpisodeHistoryEventType.Grabbed).ToList();
354	
355	                trackedDownload.HasNotifiedManualInteractionRequired = true;
356	
357	                var releaseInfo = grabbedHistories.Count > 0 ? new GrabbedReleaseInfo(grabbedHistories) : null;
358	                var manualInteractionEvent = new ManualInteractionRequiredEvent(trackedDownload, releaseInfo);
359	
360	                _eventAggregator.PublishEvent(manualInteractionEvent);
361	            }
362	        }
363	
364	        private void SetImportItem(TrackedDownload trackedDownload)
365	        {
366	            trackedDownload.ImportItem = _provideImportItemService.ProvideImportItem(trackedDownload.DownloadItem, trackedDownload.ImportItem);
367	        }
368	
369	        private bool ValidatePath(TrackedDownload trackedDownload)
370	        {
371	            var downloadItemOutputPath = trackedDownload.ImportItem.OutputPath;
372	
373	            if (downloadItemOutputPath.IsEmpty)
374	            {
375	                trackedDownload.Warn("Download doesn't contain intermediate path, Skipping.");
376	                return false;
377	            }
378	
379	            if ((OsInfo.IsWindows && !downloadItemOutputPath.IsWindowsPath) ||
380	                (OsInfo.IsNotWindows && !downloadItemOutputPath.IsUnixPath))
381	            {
382	                trackedDownload.Warn("[{0}] is not a valid local path. You may need a Remote Path Mapping. Check the download troubleshooting entry on the wiki for details.", downloadItemOutputPath);
383	                return false;
384	            }
385	
386	            return true;
387	        }
388	    }
389	}
